/** Deterministic cell movement & split rules.
 * FFA movement/split launch fitted to the supplied recording; Mega inherits FFA by user request.
 * See PHYSICS-FFA-CALIBRATION.md and PHYSICS-MEGA-CALIBRATION.md.
 * The Node equivalent is generated by scripts/sync-physics.cjs. */
const LEGACY_PHYSICS = Object.freeze({
  baseSpeed: 660, speedPower: .26, minSpeed: 45, maxSpeed: 290,
  splitImpulse: 620, splitMassPower: .12, splitDrag: 3.20, splitGap: .8,
  steerDuringBoost: .32, minSplitMass: 80, mergeBase: 8, mergeMassFactor: .022,
  minMergeTime: 8, maxMergeTime: 27, cellPush: .57, mergePull: 3.7,
  eatRatio: 1.25, eatOverlap: .39, autoSplitMass: 25500,
  massDecayRate: .006, minDecayMass: 25,
  feedCost: 100, feedMass: 100, feedSpeed: 1100, feedDrag: 2.2,
  feedPlacement: 'cluster', feedInterval: .15, macroFeedInterval: .085, feedSourceGrace: .35,
});
export const worldSizeFor=mode=>mode==='mega'?7200:4800;
export const FFA_PHYSICS = Object.freeze({
  ...LEGACY_PHYSICS,
  baseSpeed: 370,
  splitImpulse: 340, splitDrag: 1.8, splitGap: 0,
  steerDuringBoost: .75, splitCollisionDelay: .5,
  minMergeTime: 15, maxMergeTime: 30,
  feedCost: 18, feedMass: 14, feedSpeed: 900, feedDrag: 2.6,
  feedPlacement: 'cell', feedInterval: .14, macroFeedInterval: .08,
});
export const MEGA_PHYSICS = Object.freeze({
  // FFA feed/merge rules, with a more responsive Mega launch and run at large masses.
  ...FFA_PHYSICS,
  baseSpeed:560,minSpeed:55,
  splitImpulse:780,splitDrag:2.8,splitMassPower:.04,splitReach:1.05,
  steerDuringBoost:.85,splitCollisionDelay:.55,
  autoSplitMass: 100000,
});
export const DUAL_PHYSICS = Object.freeze({...LEGACY_PHYSICS,feedInterval:.12,macroFeedInterval:.075});
// Other modes keep their prior baseline until their own reference captures arrive.
// Preset names are compatibility identifiers, not claims of original server code.
const preset = overrides => Object.freeze({ ...LEGACY_PHYSICS, ...overrides });
export const PHYSICS_PRESETS = Object.freeze({
  vintage_ffa: FFA_PHYSICS,
  senpa_ffa: FFA_PHYSICS,
  senpa: DUAL_PHYSICS,
  classic: preset({ speedPower: .24, splitImpulse: 700, minMergeTime: 15, maxMergeTime: 30, mergeBase: 12 }),
  aster: preset({ baseSpeed: 700, splitImpulse: 700, minMergeTime: 6, maxMergeTime: 20 }),
  senpa_mega: MEGA_PHYSICS,
  aster_mega: preset({ baseSpeed: 720, splitImpulse: 780, splitDrag: 3.6, minMergeTime: 3, maxMergeTime: 9, mergeBase: 3, cellPush: .45, mergePull: 5.5 }),
  arab: preset({ baseSpeed: 700, splitImpulse: 740, splitDrag: 3.5, minMergeTime: 5, maxMergeTime: 12, mergeBase: 4, mergePull: 4.8 }),
  gota: preset({ baseSpeed: 680, splitImpulse: 820, splitDrag: 3.4, minMergeTime: 5, maxMergeTime: 14, mergeBase: 4, mergePull: 4.5 }),
  macro: preset({ baseSpeed: 760, splitImpulse: 700, minMergeTime: 5, maxMergeTime: 12, mergeBase: 4 }),
});
// Legacy mode ids still resolve, so existing rooms/tests keep working.
const LEGACY_PRESET = Object.freeze({ ffa: 'vintage_ffa', dual: 'senpa', mega: 'senpa_mega' });
export const OTHER_PHYSICS = LEGACY_PHYSICS;
export const clamp = (v,min,max) => Math.min(max,Math.max(min,v));
export const cellRadius = mass => Math.max(13,Math.sqrt(Math.max(1,mass))*2.45);
/** Accepts a preset object, a preset id, or a legacy mode id. Unknown ids fall back to vintage_ffa. */
export const physicsFor = key => (key && typeof key === 'object') ? key : (PHYSICS_PRESETS[key] || PHYSICS_PRESETS[LEGACY_PRESET[key]] || FFA_PHYSICS);
export const autoSplitMassFor = key => physicsFor(key).autoSplitMass ?? LEGACY_PHYSICS.autoSplitMass;
export const mergeDelayFor = (mass,key='ffa') => {
  const rules=physicsFor(key);
  return clamp(rules.mergeBase+Math.sqrt(Math.max(0,mass))*rules.mergeMassFactor,rules.minMergeTime,rules.maxMergeTime);
};
export const feedIntervalFor = (key='ffa',macro=false) => {
  const rules=physicsFor(key);
  return macro?rules.macroFeedInterval:rules.feedInterval;
};
let nextFeedSourceId=0;
export const BOT_MIN_MASS=300;
export const BOT_MAX_MASS=1500;
export const BOT_RESPAWN_SECONDS=300;
export const randomBotMass=(random=Math.random)=>Math.min(BOT_MAX_MASS,Math.floor(BOT_MIN_MASS+random()*(BOT_MAX_MASS-BOT_MIN_MASS+1)));

/** Find free space against EVERY fragment, including large split players. Never force an overlapping spawn. */
export function findSafeSpawn(players,mass,width,gap=100,random=Math.random,preferred=null){
  const r=cellRadius(mass),margin=r+15;
  if(margin*2>width)return null;
  const cells=players.flatMap(p=>p.cells||[]);
  const safe=point=>Number.isFinite(point?.x)&&Number.isFinite(point?.y)&&point.x>=margin&&point.x<=width-margin&&point.y>=margin&&point.y<=width-margin&&cells.every(c=>Math.hypot(c.x-point.x,c.y-point.y)>=cellRadius(c.mass)+r+gap);
  if(preferred&&safe(preferred))return{x:preferred.x,y:preferred.y};
  if(preferred&&Number.isFinite(preferred.x)&&Number.isFinite(preferred.y)){
    // A blocked requested respawn stays near that point instead of jumping across the map.
    let nearest=null,best=Infinity;
    const consider=point=>{
      if(!safe(point))return;
      const d=Math.hypot(point.x-preferred.x,point.y-preferred.y);
      if(d<best){nearest=point;best=d;}
    };
    consider({x:clamp(preferred.x,margin,width-margin),y:clamp(preferred.y,margin,width-margin)});
    for(const c of cells){
      const base=Math.atan2(preferred.y-c.y,preferred.x-c.x),clearance=cellRadius(c.mass)+r+gap+.1;
      for(let i=0;i<64;i++){
        const angle=base+i*Math.PI*2/64;
        consider({x:clamp(c.x+Math.cos(angle)*clearance,margin,width-margin),y:clamp(c.y+Math.sin(angle)*clearance,margin,width-margin)});
      }
    }
    if(nearest)return nearest;
  }
  for(let i=0;i<64;i++){const point={x:margin+random()*(width-margin*2),y:margin+random()*(width-margin*2)};if(safe(point))return point;}
  // A deterministic grid also handles an unlucky random generator or crowded arenas.
  let best=null,bestDistance=Infinity;
  for(let x=0;x<11;x++)for(let y=0;y<11;y++){
    const point={x:margin+x*(width-margin*2)/10,y:margin+y*(width-margin*2)/10};
    if(!safe(point))continue;
    const d=preferred?Math.hypot(point.x-preferred.x,point.y-preferred.y):0;
    if(d<bestDistance){best=point;bestDistance=d;}
  }
  return best;
}

export function maintainBots(players,time,width,random=Math.random){
  for(const p of players){
    if(!p.npc)continue;
    if(p.cells.length){
      const mass=p.cells.reduce((s,c)=>s+c.mass,0);
      if(mass>BOT_MAX_MASS)for(const c of p.cells)c.mass*=BOT_MAX_MASS/mass;
      p.respawnAt=null;continue;
    }
    if(p.respawnAt==null)p.respawnAt=time+BOT_RESPAWN_SECONDS;
    if(time<p.respawnAt||time<(p.nextSpawnAttemptAt||0))continue;
    const mass=randomBotMass(random),point=findSafeSpawn(players,mass,width,100,random);
    if(!point){p.nextSpawnAttemptAt=time+1;continue;}
    p.cells=[{...point,mass,color:p.color,vx:0,vy:0,mergeAt:0}];p.target={...point};
    p.heading=random()*Math.PI*2;p.aiHuntUntil=0;p.respawnAt=null;p.nextSpawnAttemptAt=0;p.pendingSplits=[];p.spawnShieldUntil=time+1.5;
  }
}

export function decayMass(players,dt,mode='ffa'){
  const rules=physicsFor(mode),factor=Math.exp(-(rules.massDecayRate??.006)*Math.max(0,dt));
  for(const p of players)for(const c of p.cells||[])if(c.mass>(rules.minDecayMass??25))c.mass=Math.max(rules.minDecayMass??25,c.mass*factor);
}

/** Dual feeds outside its cluster. FFA/Mega feed from each cell and can feed sibling cells. */
export function ejectMass(player,food,time,width,mode='ffa'){
  if(!player?.cells?.length)return 0;
  const rules=physicsFor(mode),cost=rules.feedCost??100,pelletMass=rules.feedMass??cost,pelletRadius=Math.sqrt(pelletMass)*.85;
  let count=0;
  for(const c of player.cells){
    if(food.length>=6000)break;
    if(c.mass<=cost+25)continue;
    const dx=(player.target?.x??c.x)-c.x,dy=(player.target?.y??c.y)-c.y,length=Math.hypot(dx,dy);
    const ux=length>.001?dx/length:1,uy=length>.001?dy/length:0;
    let travel=cellRadius(c.mass-cost)+pelletRadius+12;
    for(const other of rules.feedPlacement==='cluster'?player.cells:[]){
      const ox=other.x-c.x,oy=other.y-c.y,along=ox*ux+oy*uy,side2=ox*ox+oy*oy-along*along;
      const clearance=cellRadius(other.mass)+pelletRadius+12;
      if(side2<clearance*clearance)travel=Math.max(travel,along+Math.sqrt(clearance*clearance-Math.max(0,side2)));
    }
    const point={x:c.x+ux*travel,y:c.y+uy*travel};
    // Firing into a wall must not clamp the pellet back inside its sender.
    if(point.x<pelletRadius||point.x>width-pelletRadius||point.y<pelletRadius||point.y>width-pelletRadius)continue;
    c.mass-=cost;count++;
    c.feedSourceId??=++nextFeedSourceId;
    food.push({...point,mass:pelletMass,color:player.color||c.color,ejected:true,ownerId:player.id,sourceId:c.feedSourceId,bornAt:time,
      ownerCollectAt:rules.feedPlacement==='cluster'?time+.6:time,sourceCollectAt:time+rules.feedSourceGrace,
      expiresAt:time+12,drag:rules.feedDrag??2.2,vx:ux*(rules.feedSpeed??1100),vy:uy*(rules.feedSpeed??1100)});
  }
  return count;
}

export function splitCell(player,c,time,width,mode='ffa') {
  if(!player?.cells?.includes(c))return null;
  const rules=physicsFor(mode);
  if(c.mass<rules.minSplitMass)return null;
  const dx=(player.target?.x??c.x)-c.x,dy=(player.target?.y??c.y)-c.y;
  const length=Math.hypot(dx,dy)||1;
  // If the pointer is directly over the cell, preserve the last target angle.
  const ux=length===1 && dx===0 && dy===0 ? 1 : dx/length;
  const uy=length===1 && dx===0 && dy===0 ? 0 : dy/length;
  const half=c.mass/2;
  c.mass=half;
  const collideAt=time+(rules.splitCollisionDelay??.15);
  c.collideAt=collideAt;
  const launch=Math.max(rules.splitImpulse * Math.pow(1000/Math.max(100,half),rules.splitMassPower),
    cellRadius(half)*(rules.splitReach||0)*rules.splitDrag);
  const distance=cellRadius(half)*rules.splitGap;
  const duration=mergeDelayFor(half,mode);
  c.mergeAt=Math.max(c.mergeAt||0,time+duration);
  return {
    x:clamp(c.x+ux*distance,cellRadius(half),width-cellRadius(half)),
    y:clamp(c.y+uy*distance,cellRadius(half),width-cellRadius(half)),
    mass:half,color:c.color,collideAt,
    vx:ux*launch,vy:uy*launch,mergeAt:c.mergeAt,
  };
}

export function splitCells(player,time,width,maxCells,mode='ffa',minimumMass=null) {
  if (!player?.cells?.length) return 0;
  const rules=physicsFor(mode), original=[...player.cells];
  let free=maxCells-player.cells.length, spawned=0;
  for (const c of original) {
    if(free<=0) break;
    if(c.mass < (minimumMass??rules.minSplitMass)) continue;
    const child=splitCell(player,c,time,width,mode);
    if(!child)continue;
    player.cells.push(child);
    spawned++;free--;
  }
  return spawned;
}

/** Multi-splits spread over simulation ticks so later generations launch from moving parents. */
export function startSplitMacro(player,count,time,width,maxCells,mode='ffa'){
  if(!player?.cells?.length)return 0;
  const rounds=Math.max(1,Math.min(6,Math.floor(Number(count)||1)));
  const spawned=splitCells(player,time,width,maxCells,mode);
  player.pendingSplits=player.pendingSplits||[];
  for(let i=1;i<rounds&&player.pendingSplits.length<12;i++)player.pendingSplits.push(time+i*.04);
  player.pendingSplits.sort((a,b)=>a-b);
  return spawned;
}
export function stepSplitMacro(player,time,width,maxCells,mode='ffa'){
  if(!player?.cells?.length){if(player)player.pendingSplits=[];return;}
  while(player.pendingSplits?.length&&player.pendingSplits[0]<=time+1e-8){
    player.pendingSplits.shift();splitCells(player,time,width,maxCells,mode);
  }
}

export function findSplitHunt(bot,players,time,width,maxCells,mode='ffa'){
  if(!bot?.npc||bot.cells?.length!==1||bot.cells.length>=maxCells)return null;
  const rules=physicsFor(mode),source=bot.cells[0],half=source.mass/2;
  if(source.mass<rules.minSplitMass*2)return null;

  let selected=null;
  for(const prey of players){
    if(prey===bot||!prey.cells?.length||time<(prey.spawnShieldUntil||0))continue;
    for(const target of prey.cells){
      if(half<=target.mass*rules.eatRatio)continue;
      const distance=Math.hypot(target.x-source.x,target.y-source.y);
      if(distance>520)continue;
      const threatened=players.some(enemy=>enemy!==bot&&enemy.cells?.some(cell=>cell!==target&&
        cell.mass>half*rules.eatRatio&&Math.hypot(cell.x-source.x,cell.y-source.y)<420
      ));
      if(threatened)continue;
      if(!selected||distance<selected.distance)selected={prey,target,source,distance};
    }
  }
  return selected;
}

export function moveCells(player,dt,time,width,mode='ffa',sensitivity=1) {
  if(!player?.cells?.length || dt<=0) return;
  const rules=physicsFor(mode),cells=player.cells;
  // A shared cursor target keeps separated fragments controllable without snapping them.
  for(const c of cells){
    const dx=(player.target?.x??c.x)-c.x,dy=(player.target?.y??c.y)-c.y;
    const length=Math.hypot(dx,dy);
    const speed=clamp(rules.baseSpeed/Math.pow(Math.max(25,c.mass),rules.speedPower),rules.minSpeed,rules.maxSpeed)*clamp(sensitivity,.2,2);
    const boost=Math.hypot(c.vx||0,c.vy||0);
    const steer=boost>speed*.7?rules.steerDuringBoost:1;
    if(length>2&&!player.movementStopped){
      const stride=Math.min(length-2,speed*steer*dt);
      c.x+=dx/length*stride;c.y+=dy/length*stride;
    }
    // Closed-form damping makes launch travel nearly independent of render tick rate.
    const drag=Math.exp(-rules.splitDrag*dt);
    const distanceFactor=(1-drag)/rules.splitDrag;
    c.x+=(c.vx||0)*distanceFactor;c.y+=(c.vy||0)*distanceFactor;
    c.vx=(c.vx||0)*drag;c.vy=(c.vy||0)*drag;
    const radius=cellRadius(c.mass);
    c.x=clamp(c.x,radius,width-radius);
    c.y=clamp(c.y,radius,width-radius);
  }
  // Before merge becomes legal, cells repel; afterwards they are allowed to overlap
  // and attract each other so they can actually rejoin, unlike the previous version.
  for(let i=0;i<cells.length;i++) for(let j=i+1;j<cells.length;j++){
    const a=cells[i],b=cells[j];
    let dx=b.x-a.x,dy=b.y-a.y,distance=Math.hypot(dx,dy);
    if(distance<.001){
      // Coincident fragments separate along their launch direction, with an unbiased fallback.
      const vx=(b.vx||0)-(a.vx||0),vy=(b.vy||0)-(a.vy||0),angle=Math.hypot(vx,vy)>.01?Math.atan2(vy,vx):(i*17+j*31)*2.3999632297;
      dx=Math.cos(angle)*.001;dy=Math.sin(angle)*.001;distance=.001;
    }
    const nx=dx/distance,ny=dy/distance;
    const mergeReady=time>=Math.max(a.mergeAt||0,b.mergeAt||0);
    if(!mergeReady){
      if(time<Math.max(a.collideAt||0,b.collideAt||0))continue;
      const minDistance=(cellRadius(a.mass)+cellRadius(b.mass))*.93;
      if(distance<minDistance){
        const ramp=clamp((time-Math.max(a.collideAt||0,b.collideAt||0))/.2,0,1);
        const strength=rules.cellPush/Math.sqrt(Math.max(1,cells.length/4));
        const push=(minDistance-distance)*(1-Math.pow(1-strength,dt*30))*ramp;
        const pushA=push*b.mass/(a.mass+b.mass),pushB=push*a.mass/(a.mass+b.mass);
        a.x=clamp(a.x-nx*pushA,cellRadius(a.mass),width-cellRadius(a.mass));
        a.y=clamp(a.y-ny*pushA,cellRadius(a.mass),width-cellRadius(a.mass));
        b.x=clamp(b.x+nx*pushB,cellRadius(b.mass),width-cellRadius(b.mass));
        b.y=clamp(b.y+ny*pushB,cellRadius(b.mass),width-cellRadius(b.mass));
      }
    }else {
      const reach=(cellRadius(a.mass)+cellRadius(b.mass))*1.18;
      if(distance<reach){
        const closeness=Math.min(distance,reach);
        const pull=Math.min(closeness*.5,rules.mergePull*dt*closeness);
        const weightedA=b.mass/(a.mass+b.mass);
        const weightedB=a.mass/(a.mass+b.mass);
        a.x+=nx*pull*weightedA;a.y+=ny*pull*weightedA;
        b.x-=nx*pull*weightedB;b.y-=ny*pull*weightedB;
      }
    }
  }
  mergeCells(player,time,width,mode);
}

export function mergeCells(player,time,width,mode='ffa'){
  const cells=player?.cells;if(!cells||cells.length<2)return 0;
  let count=0;
  for(let i=0;i<cells.length;i++){
    const a=cells[i];
    for(let j=i+1;j<cells.length;j++){
      const b=cells[j];
      if(time<Math.max(a.mergeAt||0,b.mergeAt||0)) continue;
      const d=Math.hypot(a.x-b.x,a.y-b.y);
      if(d>Math.max(cellRadius(a.mass),cellRadius(b.mass))*.74) continue;
      const total=a.mass+b.mass;
      a.x=clamp((a.x*a.mass+b.x*b.mass)/total,cellRadius(total),width-cellRadius(total));
      a.y=clamp((a.y*a.mass+b.y*b.mass)/total,cellRadius(total),width-cellRadius(total));
      a.vx=((a.vx||0)*a.mass+(b.vx||0)*b.mass)/total;
      a.vy=((a.vy||0)*a.mass+(b.vy||0)*b.mass)/total;
      a.mass=total;a.mergeAt=time;
      cells.splice(j,1);j--;count++;
    }
  }
  return count;
}

export function eatCells(players,mode='ffa',time=Infinity) {
  const rules=physicsFor(mode);
  let eaten=0;
  const alive=players.filter(p=>p.cells?.length);
  for(const big of alive){
    for(const small of alive){
      if(big===small||!small.cells.length||time<(small.spawnShieldUntil||0))continue;
      for(const a of big.cells){
        for(let j=small.cells.length-1;j>=0;j--){
          const b=small.cells[j];
          if(a.mass<=b.mass*rules.eatRatio)continue;
          const maxDistance=cellRadius(a.mass)-cellRadius(b.mass)*rules.eatOverlap;
          if(Math.hypot(a.x-b.x,a.y-b.y)>=maxDistance)continue;
          const gain=big.npc?Math.min(b.mass,Math.max(0,BOT_MAX_MASS-big.cells.reduce((s,c)=>s+c.mass,0))):b.mass;
          a.mass+=gain;small.cells.splice(j,1);eaten++;
          if(small.npc&&!small.cells.length&&Number.isFinite(time))small.respawnAt=time+BOT_RESPAWN_SECONDS;
        }
      }
    }
  }
  return eaten;
}

/** First eligible cell on the pellet's flight segment, independent of player array order. */
export function findFoodRecipient(pellet,players,time=Infinity){
  const startX=pellet.ejected?(pellet.previousX??pellet.x):pellet.x;
  const startY=pellet.ejected?(pellet.previousY??pellet.y):pellet.y;
  const dx=pellet.x-startX,dy=pellet.y-startY,length2=dx*dx+dy*dy;
  let receiver=null,first=Infinity;
  for(const p of players){
    if(pellet.ejected&&pellet.ownerId===p.id&&time<(pellet.ownerCollectAt||0))continue;
    for(const c of p.cells||[]){
      if(pellet.ejected&&pellet.ownerId===p.id&&pellet.sourceId===c.feedSourceId&&time<(pellet.sourceCollectAt||0))continue;
      const radius=cellRadius(c.mass);
      if(c.x<Math.min(startX,pellet.x)-radius||c.x>Math.max(startX,pellet.x)+radius||c.y<Math.min(startY,pellet.y)-radius||c.y>Math.max(startY,pellet.y)+radius)continue;
      const ox=startX-c.x,oy=startY-c.y,outside=ox*ox+oy*oy-radius*radius;
      let at=0;
      if(outside>0){
        if(!length2)continue;
        const b=ox*dx+oy*dy,disc=b*b-length2*outside;
        if(disc<0)continue;
        at=(-b-Math.sqrt(disc))/length2;
        if(at<0||at>1)continue;
      }
      if(!pellet.ejected)return{player:p,cell:c,at};
      if(at<first||(at===first&&c.mass>(receiver?.cell.mass??0))){first=at;receiver={player:p,cell:c,at};}
    }
  }
  return receiver;
}

export function absorbFood(players,food,mode='ffa',time=Infinity) {
  let gained=0;
  for(let k=food.length-1;k>=0;k--){
    const pellet=food[k];
    const hit=findFoodRecipient(pellet,players,time);
    if(!hit)continue;
    const {player:p,cell:c}=hit;
    const gain=p.npc?Math.min(pellet.mass,Math.max(0,BOT_MAX_MASS-p.cells.reduce((s,c)=>s+c.mass,0))):pellet.mass;
    c.mass+=gain;food.splice(k,1);gained++;
  }
  return gained;
}
